  source={**{k:v for k,v in c.items() if k!='status'},'id':'rak37-'+key,'title':title,'publisher':publisher,'publishedAt':publication,'firstAvailableAt':c['retrievedAt'],'primaryEvidence':True,'classification':'primary_developer_investor_report' if pages else 'primary_operator_announcement','publicationDateStatus':'Unknown; reporting period and upload path do not establish publication day' if pages else 'Date displayed by the issuing organisation; this captured vintage was first verified at retrieval','availabilityBasis':'Current source vintage first verified at retrieval; no historical backtest availability inferred','reviewedPages':pages,'visualPagesChecked':bool(pages),'licence':'rights_pending: minimal attributed facts only; raw PDFs, articles and rendered pages are not redistributed','rawBodyRedistributed':False}
