 packet={'version':1,'passId':'rak-financial-pass37-20261008','asOf':s['asOf'],'priorVersion':s['version'],'candidateVersion':'20261008-enrichment-v37','sources':sources,'facts':facts,'seriesLinks':[],'recordIdentityChecks':checks,'nativeSalesSnapshots':native,'collection':collection,'conflicts':[{'field':'units_launched','resolution':'Quattro Q2 and FY2024 launched populations differ; both dated snapshots retained. No subtraction presented as comparable sales flows.'},{'field':'hotel_openings','resolution':'Hotel opening reports retain native date semantics and superseded targets; they do not establish residential occupancy.'}],'excludedCandidates':oldpacket['excludedCandidates']+[{'field':'corporate_investment_property_valuations_and_rents','reason':'2024 and 2025 audited statements report portfolio totals and valuation-input ranges without exact catalogue property identities. No allocation to projects or communities, per-unit division or current valuation credit.'},{'source':'minor-opening-2024','reason':'Direct operator capture failed; no source or coverage credit. Exact Anantara opening date is separately supported by reviewed developer report.'}],'methodology':'Visually reviewed native table and timeline, checksummed primary captures, exact identity proofs and separately preserved reporting vintages. No average prices, registered sale inference, aggregate portfolio valuation allocation, NIL-to-zero conversion, hotel-to-residence fan-out or inferred historical online availability.'}
